// api/brand-asset.js — serve Guardian brand JPEGs embedded in-repo.
// History: chunk modules (api/_brand_*) were referenced but never fully committed,
// which crashed the function. Empty BRAND_ASSETS then returned 503 by design.
// Payloads below are complete SOI…EOI JPEGs so /brand/* rewrites return 200.

const BRAND_ASSETS = {
  'guardian-wordmark.jpg':
    '',
  'guardian-wordmark@2x.jpg':
    '',
  'guardian-wordmark-og.jpg':
    '',
  'guardian-x-banner.jpg':
    '',
  'guardian-x-banner@2x.jpg':
    '',
};

export default function handler(req, res) {
  try {
    const file = String((req.query && req.query.file) || '').replace(/^\/+/, '');
    const payload = BRAND_ASSETS[file];
    if (!payload) {
      res.statusCode = 503;
      res.setHeader('Content-Type', 'text/plain; charset=utf-8');
      res.setHeader('Cache-Control', 'no-store');
      return res.end('brand asset unavailable — use text fallback');
    }
    const buf = Buffer.from(payload, 'base64');
    res.statusCode = 200;
    res.setHeader('Content-Type', 'image/jpeg');
    res.setHeader('Cache-Control', 'public, max-age=86400, stale-while-revalidate=604800');
    res.setHeader('Content-Length', String(buf.length));
    return res.end(buf);
  } catch (e) {
    res.statusCode = 503;
    res.setHeader('Content-Type', 'text/plain; charset=utf-8');
    res.setHeader('Cache-Control', 'no-store');
    return res.end('brand asset error');
  }
}
